 void MprisService::onVolumeDown()
 {
-    if (m_activePlayer && m_activePlayer->canControl()) {
-        m_activePlayer->changeVolume(-0.05, true);
+    changeVolume(-0.05);
+}
+
+void MprisService::changeVolume(double delta)
+{
+    if (!m_activePlayer || !m_activePlayer->canControl()) {
+        return;
+    }
+
+#if HAVE_PULSEAUDIOQT
+    // Connect early so the streams are known if the player turns out to ignore its Volume property
+    PulseAudioQt::Context::instance();
+    connect(m_activePlayer, &PlayerContainer::volumeChangeIgnored, this, &MprisService::onVolumeChangeIgnored, Qt::UniqueConnection);
+#endif
+    m_activePlayer->changeVolume(delta, true);
+}
+
+void MprisService::onVolumeChangeIgnored(double delta, bool showOSD)
+{
+#if HAVE_PULSEAUDIOQT
+    auto player = qobject_cast<PlayerContainer *>(sender());
+    if (!player || player->instancePid() == 0) {
+        return;
+    }
+
+    // Change the volume of the player's audio streams instead, which may come from one of its child processes
+    auto isPlayerProcess = [playerPid = player->instancePid()](unsigned pid) {
+        for (int depth = 0; depth < 5 && pid > 1; ++depth) {
+            if (pid == playerPid) {
+                return true;
+            }
+            QFile stat(QStringLiteral("/proc/%1/stat").arg(pid));
+            if (!stat.open(QIODevice::ReadOnly)) {
+                return false;
+            }
+            const QByteArray line = stat.readAll();
+            pid = line.mid(line.lastIndexOf(')') + 2).split(' ').value(1).toUInt();
+        }
+        return false;
+    };
+
+    qint64 newVolume = -1;
+    const auto sinkInputs = PulseAudioQt::Context::instance()->sinkInputs();
+    for (PulseAudioQt::SinkInput *sinkInput : sinkInputs) {
+        if (!sinkInput->isVolumeWritable() || !isPlayerProcess(sinkInput->properties().value(QStringLiteral("application.process.id")).toUInt())) {
+            continue;
+        }
+        if (newVolume < 0) {
+            const qint64 volume = sinkInput->volume();
+            newVolume = qBound<qint64>(PulseAudioQt::minimumVolume(),
+                                       volume + qRound64(delta * PulseAudioQt::normalVolume()),
+                                       std::max(volume, PulseAudioQt::normalVolume()));
+        }
+        sinkInput->setVolume(newVolume);
+    }
+
+    if (newVolume >= 0 && showOSD) {
+        player->showVolumeOSD(double(newVolume) / PulseAudioQt::normalVolume());
     }
+#else
+    Q_UNUSED(delta)
+    Q_UNUSED(showOSD)
+#endif
 }

