 void PlayerContainer::changeVolume(double delta, bool showOSD)
 {
+    if (m_ignoresVolume) {
+        Q_EMIT volumeChangeIgnored(delta, showOSD);
+        return;
+    }
+
     // Not relying on property/setProperty to avoid doing blocking DBus calls
     const double newVolume = qBound(0.0, m_volume + delta, std::max(m_volume.value(), 1.0));
     const double oldVolume = m_volume;

+    if (qFuzzyCompare(newVolume, oldVolume)) {
+        if (showOSD) {
+            showVolumeOSD(newVolume);
+        }
+        return;
+    }
+
     // Update the container value right away so when calling this method in quick succession
     // (mouse wheeling the tray icon) next call already gets the new value
     m_volume = newVolume;

+    // Only trust the change once the player reports it, as some players accept the call but ignore it
+    if (!m_volumeChangeTimer) {
+        m_volumeChangeTimer = new QTimer(this);
+        m_volumeChangeTimer->setSingleShot(true);
+        m_volumeChangeTimer->setInterval(500);
+        connect(m_volumeChangeTimer, &QTimer::timeout, this, [this] {
+            m_ignoresVolume = true;
+            m_pendingVolumeChanges = 0;
+            m_volume = m_volume - m_pendingVolumeDelta;
+            Q_EMIT volumeChangeIgnored(std::exchange(m_pendingVolumeDelta, 0.0), std::exchange(m_pendingVolumeOSD, false));
+        });
+    }
+    ++m_pendingVolumeChanges;
+    m_pendingVolumeDelta += newVolume - oldVolume;
+    m_pendingVolumeOSD = m_pendingVolumeOSD || showOSD;
+    if (!m_volumeChangeTimer->isActive()) {
+        m_volumeChangeTimer->start();
+    }
+
     QDBusPendingCall call = m_propsIface->Set(m_playerIface->interface(), QStringLiteral("Volume"), QDBusVariant(newVolume));
     auto watcher = new QDBusPendingCallWatcher(call, this);
-    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, oldVolume, showOSD](QDBusPendingCallWatcher *watcher) {
+    connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, oldVolume](QDBusPendingCallWatcher *watcher) {
         QDBusPendingReply<void> reply = *watcher;
         watcher->deleteLater();
         if (!reply.isValid()) {
+            m_volumeChangeTimer->stop();
+            m_pendingVolumeChanges = 0;
+            m_pendingVolumeDelta = 0.0;
+            m_pendingVolumeOSD = false;
             m_volume = oldVolume;
-            return;
         }
+    });
+}

-        if (showOSD) {
-            QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
-                                                              QStringLiteral("/org/kde/osdService"),
-                                                              QStringLiteral("org.kde.osdService"),
-                                                              QStringLiteral("mediaPlayerVolumeChanged"));
+void PlayerContainer::showVolumeOSD(double volume)
+{
+    QDBusMessage msg = QDBusMessage::createMethodCall(QStringLiteral("org.kde.plasmashell"),
+                                                      QStringLiteral("/org/kde/osdService"),
+                                                      QStringLiteral("org.kde.osdService"),
+                                                      QStringLiteral("mediaPlayerVolumeChanged"));

-            msg.setArguments({qRound(m_volume * 100), m_identity, m_iconName});
+    msg.setArguments({qRound(volume * 100), m_identity, m_iconName});

-            QDBusConnection::sessionBus().asyncCall(msg);
-        }
-    });
+    QDBusConnection::sessionBus().asyncCall(msg);
 }

