+                m_volumeChangeTimer->start();
+                continue;
+            }
+            if (m_volumeChangeTimer) {
+                m_volumeChangeTimer->stop();
+            }
+            m_pendingVolumeDelta = 0.0;
+            m_pendingVolumeOSD = false;
+            m_volume = volume;
